// Годы выпуска: «с 17 г.в.» -> «с 2017», «12-16 г.в.» -> «2012–2016», «до 12 г.в.» -> «до 2012»
window.AS_years = function (y) {
  if (!y) return "все годы";
  var full = function (s) { return String(s).length === 2 ? (Number(s) > 50 ? "19" : "20") + s : s; };
  return y.replace(" г.в.", "").replace(/^с (\d{2})$/, function (_, a) { return "с " + full(a); })
          .replace(/^до (\d{2})$/, function (_, a) { return "до " + full(a); })
          .replace(/^(\d{2})-(\d{2})$/, function (_, a, b) { return full(a) + "–" + full(b); });
};
